# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::EntryOwner do
  # "The entry list and read-after-write reads go to the current owner: Timekeeping, or the prepared
  # monolith's local tables, or `timesheet_entries` in the legacy state."
  # Every handoff raises the generation and an abort keeps it, so generation 3 alone does not mean
  # a rollback ever completed.
  it "keeps reading the legacy tables after two aborted first cutovers raised the generation to 3" do
    ownership = TimekeepingOwnership.current
    ownership.update!(generation: 3, owner: "monolith", handoff_step: nil)

    expect(ownership.reload.monolith_store).to eq("legacy")
    expect(described_class.for(ownership)).to eq(:legacy)

    ownership.update!(generation: 4, handoff_step: "close_admission")
    expect(described_class.for(ownership.reload)).to eq(:legacy)
  end
end
